use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicBool,AtomicU64,Ordering::Relaxed};use js_runtime::{Runtime,Value,EnvId,JsResult};
struct Counter;#[global_allocator]static ALLOCATOR:Counter=Counter;static ACTIVE:AtomicBool=AtomicBool::new(false);static ALLOC:AtomicU64=AtomicU64::new(0);static REALLOC:AtomicU64=AtomicU64::new(0);static BYTES:AtomicU64=AtomicU64::new(0);
unsafe impl GlobalAlloc for Counter{unsafe fn alloc(&self,l:Layout)->*mut u8{let p=unsafe{System.alloc(l)};if !p.is_null()&&ACTIVE.load(Relaxed){ALLOC.fetch_add(1,Relaxed);BYTES.fetch_add(l.size()as u64,Relaxed);}p}unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{let p=unsafe{System.alloc_zeroed(l)};if !p.is_null()&&ACTIVE.load(Relaxed){ALLOC.fetch_add(1,Relaxed);BYTES.fetch_add(l.size()as u64,Relaxed);}p}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{let p=unsafe{System.realloc(p,l,n)};if !p.is_null()&&ACTIVE.load(Relaxed){REALLOC.fetch_add(1,Relaxed);BYTES.fetch_add(n as u64,Relaxed);}p}unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}}
fn reset(){ALLOC.store(0,Relaxed);REALLOC.store(0,Relaxed);BYTES.store(0,Relaxed)}
fn rounds(rt:&mut Runtime,_:Value,args:&[Value],parent:EnvId)->JsResult<Value>{let reuse=matches!(args.first(),Some(Value::Bool(true)));let env=rt.child_env(parent);for(name,value)in[("battles",23.0),("warmup",0.0),("battleIndex",0.0)]{rt.declare(env,name,Value::Number(value))?;}let source=rt.object();for i in 0..47{let key=rt.string(&format!("k{i}"));rt.define_data(source,key,Value::Number(if i==0{-0.0}else{i as f64*1.125}),true,true,true)?;}rt.declare(env,"keptSource",source)?;let source_id=rt.object_id(source)?;let mut seen=std::collections::HashSet::new();let(mut reused,mut allocations,mut reallocations,mut bytes)=(0,0,0,0);for round in 0..23{reset();ACTIVE.store(true,Relaxed);let output=rt.try_native_copy_obj_with_capacity_reuse(source,env,reuse);ACTIVE.store(false,Relaxed);let(a,r,b)=(ALLOC.load(Relaxed),REALLOC.load(Relaxed),BYTES.load(Relaxed));allocations+=a;reallocations+=r;bytes+=b;let output=output?.unwrap();let id=rt.object_id(output)?;assert_ne!(id,source_id);if !seen.insert(id){reused+=1;}assert_eq!(rt.own_keys(source,true)?,rt.own_keys(output,true)?);for key in rt.own_keys(source,true)?{let(Value::Number(a),Value::Number(b))=(rt.get(source,key)?,rt.get(output,key)?)else{panic!()};assert_eq!(a.to_bits(),b.to_bits());}rt.assign(env,"battleIndex",Value::Number(round as f64),false)?;rt.collect_native_battle_backedge(env,parent)?;}assert_eq!(reused,22);println!("{{\"reuse\":{},\"rounds\":23,\"recycledDestinations\":{},\"allocations\":{},\"reallocations\":{},\"requestedBytes\":{}}}",reuse,reused,allocations,reallocations,bytes);Ok(Value::Number(allocations as f64))}
fn main()->JsResult<()>{for reuse in[false,true]{let mut rt=Runtime::new();let f=rt.make_closure(rounds,rt.global_env,1,"__nativeRun");rt.set_function_source(f,&include_str!("../src/native_battle_run.js").encode_utf16().collect::<Vec<_>>())?;rt.enable_native_battle_gc();rt.call(f,Value::Undefined,&[Value::Bool(reuse)])?;assert_eq!(rt.native_battle_gc_stats().collections,23);}Ok(())}
